'use client';

import { useActionState } from 'react';

async function submitContactForm(prevState: any, formData: FormData) {
  'use server';

  const name = formData.get('name');
  const email = formData.get('email');
  const message = formData.get('message');

  // JavaScript validation in server action
  if (!name || typeof name !== 'string' || name.trim() === '') {
    return {
      success: false,
      error: 'Name is required'
    };
  }

  if (!email || typeof email !== 'string' || email.trim() === '') {
    return {
      success: false,
      error: 'Email is required'
    };
  }

  // Basic email format validation
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    return {
      success: false,
      error: 'Please provide a valid email address'
    };
  }

  if (!message || typeof message !== 'string' || message.trim() === '') {
    return {
      success: false,
      error: 'Message is required'
    };
  }

  // Simulate saving the contact message
  console.log('Contact form submitted:', { name, email, message });

  return {
    success: true,
    message: 'Thank you for contacting us! We will get back to you soon.'
  };
}

export default function ContactForm() {
  const [state, formAction, isPending] = useActionState(submitContactForm, null);

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px' }}>
      <h2>Contact Us</h2>

      <form action={formAction} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        <div>
          <label htmlFor="name" style={{ display: 'block', marginBottom: '5px' }}>
            Name:
          </label>
          <input
            type="text"
            id="name"
            name="name"
            required
            style={{
              width: '100%',
              padding: '8px',
              fontSize: '16px',
              border: '1px solid #ccc',
              borderRadius: '4px'
            }}
          />
        </div>

        <div>
          <label htmlFor="email" style={{ display: 'block', marginBottom: '5px' }}>
            Email:
          </label>
          <input
            type="email"
            id="email"
            name="email"
            required
            style={{
              width: '100%',
              padding: '8px',
              fontSize: '16px',
              border: '1px solid #ccc',
              borderRadius: '4px'
            }}
          />
        </div>

        <div>
          <label htmlFor="message" style={{ display: 'block', marginBottom: '5px' }}>
            Message:
          </label>
          <textarea
            id="message"
            name="message"
            required
            rows={5}
            style={{
              width: '100%',
              padding: '8px',
              fontSize: '16px',
              border: '1px solid #ccc',
              borderRadius: '4px',
              fontFamily: 'inherit'
            }}
          />
        </div>

        <button
          type="submit"
          disabled={isPending}
          style={{
            padding: '10px 20px',
            fontSize: '16px',
            backgroundColor: isPending ? '#ccc' : '#0070f3',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: isPending ? 'not-allowed' : 'pointer'
          }}
        >
          {isPending ? 'Submitting...' : 'Submit'}
        </button>

        {state?.error && (
          <div style={{
            padding: '10px',
            backgroundColor: '#fee',
            color: '#c00',
            borderRadius: '4px',
            border: '1px solid #fcc'
          }}>
            {state.error}
          </div>
        )}

        {state?.success && (
          <div style={{
            padding: '10px',
            backgroundColor: '#efe',
            color: '#0a0',
            borderRadius: '4px',
            border: '1px solid #cfc'
          }}>
            {state.message}
          </div>
        )}
      </form>
    </div>
  );
}

